package org.racedaydreams.domain.strength;
import java.util.*;
import org.racedaydreams.domain.coaching.Immutable;
/** Original offline coaching copy and diagram specifications; no third-party assets. */
public record TechniqueGuide(String pattern,String setup,String movement,List<String> cues,List<String> mistakes,String muscles,List<String> alternatives) {
    public static TechniqueGuide forExercise(String id){
        String pattern,setup,movement,muscles;List<String> alternatives;
        switch(id){
            case "back-squat", "front-squat", "leg-press" -> {pattern="squat";setup=id.equals("leg-press")?"Sit with your back supported and feet stable on the platform.":"Set your feet comfortably apart and brace; support the load securely.";movement=id.equals("leg-press")?"Lower the platform under control, then press without locking your knees.":"Bend hips and knees together to a controlled depth, then stand through your whole foot.";muscles="Quadriceps and glutes";alternatives=Immutable.list("Goblet Squat","Leg Press");}
            case "deadlift","romanian-deadlift","trap-bar-deadlift","kettlebell-swing" -> {pattern="hinge";setup=id.equals("trap-bar-deadlift")?"Stand inside the bar with the handles alongside you; brace before lifting.":id.equals("kettlebell-swing")?"Start with the bell just ahead of you; hinge and grip with both hands.":"Stand close to the load, soften your knees and brace your trunk.";movement=id.equals("romanian-deadlift")?"Push hips back with a small knee bend; lower the bar close to your legs, then extend the hips.":id.equals("kettlebell-swing")?"Hike the bell back, then extend your hips to float it forward; guide it back into a hinge.":"Push through your feet and extend hips and knees together, then lower under control.";muscles="Glutes, hamstrings and back extensors";alternatives=Immutable.list("Romanian Deadlift","Hip Thrust");}
            case "split-squat","reverse-lunge","walking-lunge","step-up" -> {pattern="split";setup=id.equals("split-squat")?"Place the rear foot on a stable low support; leave room to bend the front knee.":id.equals("step-up")?"Place the whole working foot on a stable step of manageable height.":"Stand tall with space around you and your feet comfortably apart.";movement=id.equals("step-up")?"Drive through the foot on the step to stand up, then lower under control.":id.equals("reverse-lunge")?"Step back, bend both knees, then push through the front foot to return.":id.equals("walking-lunge")?"Step forward, bend both knees under control, then step through into the next lunge.":"Lower with control through the front leg, then stand without bouncing off the rear foot.";muscles="Quadriceps and glutes";alternatives=Immutable.list("Reverse Lunge","Step-Up","Goblet Squat");}
            case "bench-press","dumbbell-bench-press" -> {pattern="press";setup="Lie on a stable bench with feet supported; hold the load over your chest. Use appropriate rack safeties or a spotter for a barbell.";movement="Lower toward the chest with forearms supported beneath the load; press back up under control.";muscles="Chest, triceps and front shoulders";alternatives=Immutable.list("Push-Up","Machine Chest Press");}
            case "overhead-press","dumbbell-shoulder-press" -> {pattern="overhead";setup="Hold the load at shoulder level with a stable stance and braced trunk.";movement="Press overhead without leaning back excessively, then return to shoulder height under control.";muscles="Shoulders and triceps";alternatives=Immutable.list("Landmine Press","Machine Shoulder Press");}
            case "barbell-row","seated-cable-row" -> {pattern="row";setup=id.equals("barbell-row")?"Hinge at the hips with a braced trunk and arms hanging below the shoulders.":"Sit with feet supported, hold the handle and keep a comfortable upright trunk.";movement="Pull toward the lower ribs while keeping your trunk steady; extend the arms under control.";muscles="Upper back and elbow flexors";alternatives=Immutable.list("Chest-Supported Row","Dumbbell Row");}
            case "lat-pulldown","pull-up" -> {pattern="pull";setup=id.equals("pull-up")?"Grip a secure bar and start from a controlled hang.":"Sit with thighs secured and take a comfortable grip on the bar.";movement=id.equals("pull-up")?"Pull your body upward without swinging, then lower with control.":"Pull the bar toward your upper chest, then allow a controlled return overhead.";muscles="Lats, upper back and elbow flexors";alternatives=Immutable.list("Lat Pulldown","Inverted Row");}
            case "hip-thrust" -> {pattern="bridge";setup="Support your upper back on a stable bench and plant your feet; pad the load over the hips.";movement="Extend the hips with your ribs controlled; pause near level, then lower without overextending the back.";muscles="Glutes";alternatives=Immutable.list("Barbell Glute Bridge","Romanian Deadlift");}
            case "calf-raise" -> {pattern="calf";setup="Stand with stable foot support and hold something for balance if needed.";movement="Rise onto the balls of your feet, pause briefly, then lower your heels slowly through a comfortable range.";muscles="Calves";alternatives=Immutable.list("Seated Calf Raise","Single-Leg Calf Raise");}
            case "plank","side-plank" -> {pattern="plank";setup=id.equals("side-plank")?"Lie on your side with the elbow beneath the shoulder and legs stacked or staggered.":"Place your forearms on the floor with elbows under the shoulders and legs extended.";movement=id.equals("side-plank")?"Lift the hips into a straight supported line and breathe steadily; lower to finish.":"Lift into a supported line, brace gently and breathe; end the hold when control becomes difficult.";muscles="Trunk stabilisers";alternatives=Immutable.list("Dead Bug","Bird Dog");}
            case "farmers-carry" -> {pattern="carry";setup="Stand between two manageable loads and lift with a braced trunk. Record whether load is per hand in your notes.";movement="Walk with controlled steps and steady posture; place the weights down under control.";muscles="Grip, trunk and upper back";alternatives=Immutable.list("Suitcase Carry","Front Rack Carry");}
            case "lying-leg-curl" -> {pattern="curl";setup="Adjust the machine pivot near your knee and the pad above your heels; keep your hips supported.";movement="Bend the knees to curl the pad toward you, then extend under control without lifting the hips.";muscles="Hamstrings";alternatives=Immutable.list("Seated Leg Curl","Sliding Leg Curl");}
            default -> {return null;}
        }
        return new TechniqueGuide(pattern,setup,movement,Immutable.list("Start with a manageable load or variation","Use a controlled, comfortable range","Keep breathing and maintain a stable setup"),Immutable.list("Using momentum instead of control","Choosing a load that changes the intended movement","Continuing when technique deteriorates"),muscles,alternatives);
    }
}
